use serde::{Deserialize, Serialize};
use std::path::Path;
use std::process::{Command, Stdio};
use std::time::{Duration, Instant};

#[derive(Debug, Serialize, Deserialize)]
pub struct RunCommandArgs {
    pub command: String,
    pub cwd: Option<String>,
    #[serde(default = "default_timeout")]
    pub timeout_secs: u64,
    #[serde(default = "default_shell")]
    pub shell: String,
    #[serde(default)]
    pub pty: bool,
    #[serde(default)]
    pub argv: Option<Vec<String>>,
    #[serde(default)]
    pub background: bool,
    #[serde(default)]
    pub service_name: Option<String>,
}

impl Default for RunCommandArgs {
    fn default() -> Self {
        Self {
            command: String::new(),
            cwd: None,
            timeout_secs: default_timeout(),
            shell: default_shell(),
            pty: false,
            argv: None,
            background: false,
            service_name: None,
        }
    }
}

pub fn max_tool_timeout_secs() -> u64 {
    std::env::var("NEXUS_MAX_TOOL_TIMEOUT_SECS")
        .ok()
        .and_then(|v| v.parse::<u64>().ok())
        .unwrap_or(1800)
}

fn default_timeout() -> u64 {
    60
}

fn default_shell() -> String {
    #[cfg(windows)]
    return "powershell.exe".to_string();
    #[cfg(not(windows))]
    return "bash".to_string();
}

#[derive(Debug, Serialize, Deserialize)]
pub struct RunCommandResult {
    pub command: String,
    pub shell: String,
    pub exit_code: Option<i32>,
    pub stdout: String,
    pub stderr: String,
    pub duration_ms: u128,
    pub timed_out: bool,
    /// The operator's cancel (or the engine's shutdown) ended the command.
    #[serde(default)]
    pub cancelled: bool,
}

const MAX_OUTPUT_CHARS: usize = 32_000;

/// Output kept per stream: the first and last halves of MAX_OUTPUT_CHARS bytes plus a count of everything. Memory stays
/// bounded however much a command prints (400 MB of output used to be buffered whole before truncation).
struct BoundedCapture {
use serde::{Deserialize, Serialize};
use similar::{ChangeTag, TextDiff};
use std::fs::{self, File};
use std::io::{self, BufRead, BufReader, Read, Seek, SeekFrom, Write};
use std::path::Path;

#[cfg(unix)]
use std::os::unix::io::AsRawFd;

pub const MAX_READ_BYTES: usize = 8 * 1024 * 1024; // 8 MB limit per REQ-SEC-107

#[derive(Debug, Serialize, Deserialize)]
pub struct ReadFileArgs {
    pub path: String,
    pub start_line: Option<usize>,
    pub end_line: Option<usize>,
    #[serde(default)]
